B.abv=new A.c8("\u0643\u064a\u0641 \u0623\u0633\u062c\u0644 \u0639\u0645\u0644\u064a\u0629 \u0628\u064a\u0639 \u062c\u062f\u064a\u062f\u0629\u061f",'\u0661. \u0627\u0630\u0647\u0628 \u0625\u0644\u0649 \u0642\u0633\u0645 "\u0627\u0644\u0645\u0628\u064a\u0639\u0627\u062a" \u0641\u064a \u0623\u0633\u0641\u0644 \u0627\u0644\u0634\u0627\u0634\u0629.\n\u0662. \u062d\u062f\u062f \u0627\u0644\u0645\u0646\u062a\u062c\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u0631\u064a\u062f \u0627\u0644\u0639\u0645\u064a\u0644 \u0634\u0631\u0627\u0621\u0647\u0627.\n\u0663. \u0627\u0646\u0642\u0631 \u0639\u0644\u0649 \u0632\u0631 "\u0627\u0644\u062f\u0641\u0639" \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644.\n\u0664. \u062d\u062f\u062f \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646 \u0627\u0644\u062f\u0641\u0639 \u0646\u0642\u062f\u0627\u064b \u0623\u0648 \u0628\u0627\u0644\u0622\u062c\u0644 \u062b\u0645 \u0627\u062d\u0641\u0638 \u0627\u0644\u0625\u064a\u0635\u0627\u0644.')
B.abL=new A.c8("\u0643\u064a\u0641 \u0623\u0637\u0628\u0642 \u062e\u0635\u0645\u0627\u064b \u0644\u0639\u0645\u064a\u0644\u061f","\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0628\u064a\u0639 \u0641\u064a \u0634\u0627\u0634\u0629 \u0627\u0644\u062f\u0641\u0639\u060c \u0633\u062a\u062c\u062f \u062d\u0642\u0644\u0627\u064b \u0645\u062e\u0635\u0635\u0627\u064b \u0644\u0644\u062e\u0635\u0645. \u0623\u062f\u062e\u0644 \u0627\u0644\u0645\u0628\u0644\u063a \u0627\u0644\u0630\u064a \u062a\u0631\u064a\u062f \u0627\u0644\u062a\u0646\u0627\u0632\u0644 \u0639\u0646\u0647\u060c \u0648\u0633\u064a\u062a\u0645 \u062a\u0642\u0644\u064a\u0644 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b.")
B.abI=new A.c8("\u0643\u064a\u0641 \u0623\u0633\u062a\u0631\u062c\u0639 \u0645\u0646\u062a\u062c\u0627\u064b \u0645\u0628\u0627\u0639\u0627\u064b (\u0625\u0631\u062c\u0627\u0639)\u061f",'\u0661. \u0627\u0630\u0647\u0628 \u0625\u0644\u0649 \u0642\u0633\u0645 "\u0627\u0644\u0637\u0644\u0628\u0627\u062a" (\u0627\u0644\u0625\u064a\u0635\u0627\u0644\u0627\u062a).\n\u0662. \u0627\u0641\u062a\u062d \u0627\u0644\u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u0645\u0639\u0646\u064a \u0648\u0627\u0646\u0642\u0631 \u0639\u0644\u0649 \u0632\u0631 "\u0625\u0631\u062c\u0627\u0639" (Return).\n\u0663. \u0623\u062f\u062e\u0644 \u0643\u0645\u064a\u0629 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0645\u0631\u062a\u062c\u0639\u0629 \u0644\u064a\u062a\u0645 \u0625\u0639\u0627\u062f\u062a\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u062e\u0632\u0646 \u0648\u062a\u062d\u062f\u064a\u062b \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a.')
