B.abu=new A.c8("\u0686\u06c6\u0646 \u06a9\u0627\u06b5\u0627\u06cc\u06d5\u06a9\u06cc \u0646\u0648\u06ce \u0632\u06cc\u0627\u062f \u0628\u06a9\u06d5\u0645\u061f",'\u0661. \u0628\u0695\u06c6 \u0628\u06c6 \u0628\u06d5\u0634\u06cc "\u06a9\u06c6\u06af\u0627".\n\u0662. \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc (+) \u062f\u0627\u0628\u06af\u0631\u06d5.\n\u0663. \u0646\u0627\u0648\u060c \u0646\u0631\u062e\u06cc \u06a9\u0695\u06cc\u0646 \u0648 \u0646\u0631\u062e\u06cc \u0641\u0631\u06c6\u0634\u062a\u0646 \u0628\u0646\u0648\u0648\u0633\u06d5.\n\u0664. \u0698\u0645\u0627\u0631\u06d5\u06cc \u06a9\u0627\u06b5\u0627\u06a9\u0627\u0646 \u0644\u06d5 \u06a9\u06c6\u06af\u0627 \u0628\u0646\u0648\u0648\u0633\u06d5 \u0648 \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0646\u0627\u0648\u06cc \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5\u06a9\u06d5\u0634 (\u0634\u06d5\u0631\u06cc\u06a9\u06d5) \u0628\u0646\u0648\u0648\u0633\u06cc\u062a \u0648 \u062e\u06d5\u0632\u0646\u06cc \u0628\u06a9\u06d5\u06cc\u062a.')
B.abp=new A.c8("\u0686\u06c6\u0646 \u0646\u0631\u062e\u06cc \u06a9\u0627\u06b5\u0627\u06cc\u06d5\u06a9 \u0628\u06af\u06c6\u0695\u0645\u061f",'\u0644\u06d5 \u0628\u06d5\u0634\u06cc \u06a9\u06c6\u06af\u0627\u060c \u06a9\u0631\u062a\u06d5 \u0644\u06d5\u0633\u06d5\u0631 \u06a9\u0627\u06b5\u0627\u06a9\u06d5 \u0628\u06a9\u06d5 \u0648 \u067e\u0627\u0634\u0627\u0646 \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc "\u0642\u06d5\u06b5\u06d5\u0645" \u062f\u0627\u0628\u06af\u0631\u06d5 \u0628\u06c6 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646. \u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5 \u0628\u0646\u0648\u0648\u0633\u06d5 \u0648 \u062e\u06d5\u0632\u0646\u06cc \u0628\u06a9\u06d5.')
