B.abJ=new A.c8("\u0686\u06c6\u0646 \u062e\u06d5\u0631\u062c\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u06cc \u062f\u0648\u06a9\u0627\u0646 \u06cc\u0627\u0646 \u06a9\u0695\u06cc\u0646\u06cc \u06a9\u0627\u06b5\u0627 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5\u0645\u061f",'\u0628\u0695\u06c6 \u0628\u06c6 \u0628\u06d5\u0634\u06cc "\u06a9\u0695\u06cc\u0646\u06d5\u06a9\u0627\u0646" (Purchases) \u0644\u06d5 \u0633\u06d5\u0631\u06d5\u0648\u06d5\u06cc \u0634\u0627\u0634\u06d5\u06a9\u06d5. \u0644\u06d5\u0648\u06ce \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u0645\u0627\u0645\u06d5\u06b5\u06d5\u06cc \u06a9\u0695\u06cc\u0646\u06cc \u06a9\u0627\u06b5\u0627\u06cc \u0646\u0648\u06ce \u06cc\u0627\u0646 \u062e\u06d5\u0631\u062c\u06cc\u06cc\u06d5\u06a9\u0627\u0646\u062a \u062f\u0627\u062e\u06b5 \u0628\u06a9\u06d5\u06cc\u062a \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0644\u06d5 \u0642\u0627\u0632\u0627\u0646\u062c\u06d5\u06a9\u06d5\u062a \u062f\u06d5\u0631\u0628\u0686\u06ce\u062a.')
B.abO=new A.c8("\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u06b5\u0627\u06cc\u06d5\u06a9\u0645 \u06a9\u0695\u06cc \u0648 \u062f\u0648\u0627\u062a\u0631 \u06af\u06d5\u0695\u0627\u0646\u062f\u0645\u06d5\u0648\u06d5 \u0686\u06cc \u0628\u06a9\u06d5\u0645\u061f",'\u0644\u06d5\u0646\u0627\u0648 \u0647\u06d5\u0645\u0627\u0646 \u0628\u06d5\u0634\u06cc \u06a9\u0695\u06cc\u0646\u06d5\u06a9\u0627\u0646\u060c \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u067e\u0633\u0648\u06b5\u06d5\u06cc \u06a9\u0695\u06cc\u0646\u06d5\u06a9\u06d5 \u0628\u06a9\u06d5\u06cc\u062a\u06d5\u0648\u06d5 \u0648 "\u06af\u06d5\u0695\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5" \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06cc\u062a \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u067e\u0627\u0631\u06d5\u06a9\u06d5 \u0648 \u06a9\u0627\u06b5\u0627\u06a9\u06d5 \u0695\u0627\u0633\u062a \u0628\u0628\u06ce\u062a\u06d5\u0648\u06d5 \u0644\u06d5 \u0633\u06cc\u0633\u062a\u06d5\u0645\u06d5\u06a9\u06d5\u062f\u0627.')
